3	import java.util.Map;
4	
5	/**
6	 * Validates an owner's optional 4-digit {@code postcode} against the inclusive range
7	 * fixed for the owner's city region (see {@link Locality}): NSW 2000-2099, VIC
8	 * 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode,
9	 * and an absent postcode is always accepted.
10	 */
11	public final class Postcode {
12	
13	    /** Region -> inclusive {low, high} 4-digit postcode range. */
14	    private static final Map<String, int[]> REGION_RANGES = Map.of(
15	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
16	
17	    private Postcode() {
18	    }
19	
20	    /**
21	     * True when {@code postcode} is absent, the city's region is unknown, or the postcode
22	     * falls within that region's inclusive range. Assumes a non-null postcode is already
23	     * validated as four digits.
24	     */
25	    public static boolean isValidForCity(String city, String postcode) {
26	        if (postcode == null) {
27	            return true;
28	        }
29	        int[] range = REGION_RANGES.get(Locality.of(city));
30	        if (range == null) {
31	            return true;
32	        }
33	        int value = Integer.parseInt(postcode);
34	        return value >= range[0] && value <= range[1];
35	    }
36	}
