17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Collection;
20	import java.util.Locale;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
24	
25	/**
26	 * Derives an owner's {@code identityKey}: {@code normalizedTelephone|email|householdId}.
27	 * All duplicate detection is consolidated here: two owners are the same registration only
28	 * when their WHOLE identity keys are equal, and a new owner is rejected only on a full match.
29	 */
30	public final class IdentityKey {
31	
32	    private IdentityKey() {
33	    }
34	
35	    /**
36	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. An owner carries no
37	     * shared-household membership in its stored state, so the household component is empty and two
38	     * owners differ in identity only through their telephone and email.
39	     */
40	    public static String of(Owner owner) {
41	        return telephone(owner.getTelephone()) + "|" + email(owner.getEmail()) + "|";
42	    }
43	
44	    /** Reject with 409 when {@code candidate}'s whole identity key equals an existing owner's. */
45	    public static void rejectIfDuplicate(Owner candidate, Collection<Owner> existingOwners) {
46	        String key = of(candidate);
47	        for (Owner owner : existingOwners) {
48	            if (owner.isDeleted()) {
49	                continue;
50	            }
51	            if (key.equals(of(owner))) {
52	                throw new DuplicateTelephoneException(key);
53	            }
54	        }
55	    }
56	
57	    /** Digits only, so equality ignores telephone formatting differences. */
58	    private static String telephone(String telephone) {
59	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
60	    }
61	
62	    /** Lower-cased and trimmed, so equality ignores case; blank/absent emails compare equal. */
63	    private static String email(String email) {
64	        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
65	    }
66	}
