18	
19	import java.util.Collection;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.util.Household;
23	
24	/**
25	 * Signals that a new owner shares an existing owner's household (the same last name
26	 * and postcode, via their computed {@code householdId}) without opting into a shared
27	 * household. Mapped to HTTP 409 Conflict by {@link ExceptionControllerAdvice}.
28	 */
29	public class DuplicateHouseholdException extends RuntimeException {
30	
31	    public DuplicateHouseholdException(String lastName, String postcode) {
32	        super("Household already registered for: " + lastName + ", " + postcode);
33	    }
34	
35	    /**
36	     * Throw if {@code candidate} shares an existing owner's {@code householdId} (same last name
37	     * and postcode), unless {@code sharesHousehold} is set.
38	     */
39	    public static void rejectIfDuplicate(Owner candidate, boolean sharesHousehold, Collection<Owner> existingOwners) {
40	        if (sharesHousehold) {
41	            return;
42	        }
43	        String household = Household.idFor(candidate);
44	        for (Owner owner : existingOwners) {
45	            if (owner.isDeleted()) {
46	                continue;
47	            }
48	            if (household.equals(Household.idFor(owner))) {
49	                throw new DuplicateHouseholdException(candidate.getLastName(), candidate.getPostcode());
50	            }
51	        }
52	    }
53	}
