5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Assigns an owner's {@code customerCode}, de-duplicated against existing owners. When the
9	 * code computed by {@link CustomerCode} already belongs to another owner, appends
10	 * {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique.
11	 */
12	public final class UniqueCustomerCode {
13	
14	    private UniqueCustomerCode() {
15	    }
16	
17	    public static String assign(Owner owner, Collection<Owner> existing) {
18	        String base = CustomerCode.assign(owner);
19	        String code = base;
20	        int n = 1;
21	        while (isTaken(code, existing)) {
22	            code = base + "-" + (++n);
23	        }
24	        return code;
25	    }
26	
27	    private static boolean isTaken(String code, Collection<Owner> existing) {
28	        for (Owner other : existing) {
29	            if (code.equals(other.getCustomerCode())) {
30	                return true;
31	            }
32	        }
33	        return false;
34	    }
35	}
