7	/**
8	 * Counts how many existing owners share a candidate owner's first and last name,
9	 * compared case-insensitively (the {@code namesakeCount}).
10	 */
11	public final class Namesakes {
12	
13	    private Namesakes() {
14	    }
15	
16	    public static int count(Owner candidate, Collection<Owner> existing) {
17	        int namesakes = 0;
18	        for (Owner other : existing) {
19	            if (candidate.getFirstName().equalsIgnoreCase(other.getFirstName())
20	                && candidate.getLastName().equalsIgnoreCase(other.getLastName())) {
21	                namesakes++;
22	            }
23	        }
24	        return namesakes;
25	    }
26	}
