5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Soft duplicate detection. A new owner that is not a hard duplicate but shares an existing
9	 * owner's last name and postcode while having a different telephone is a <em>possible</em>
10	 * duplicate; the matching owner's id is recorded on the candidate.
11	 */
12	public final class PossibleDuplicate {
13	
14	    private PossibleDuplicate() {
15	    }
16	
17	    /** Record on {@code candidate} whether it possibly duplicates an existing owner (same last
18	     *  name and postcode, different telephone) and, if so, that owner's id. A declared household
19	     *  member ({@code sharesHousehold}) is never a suspected duplicate. */
20	    public static void assign(Owner candidate, boolean sharesHousehold, Collection<Owner> existing) {
21	        Integer match = sharesHousehold ? null : matchId(candidate, existing);
22	        candidate.setPossibleDuplicate(match != null);
23	        candidate.setPossibleDuplicateOf(match);
24	    }
25	
26	    private static Integer matchId(Owner candidate, Collection<Owner> existing) {
27	        for (Owner other : existing) {
28	            if (candidate.getPostcode() != null
29	                && candidate.getPostcode().equals(other.getPostcode())
30	                && candidate.getLastName().equalsIgnoreCase(other.getLastName())
31	                && !digits(candidate.getTelephone()).equals(digits(other.getTelephone()))) {
32	                return other.getId();
33	            }
34	        }
35	        return null;
36	    }
37	
38	    private static String digits(String telephone) {
39	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
40	    }
41	}
