193	        BindingErrorsResponse errors = new BindingErrorsResponse();
194	        BindingResult bindingResult = e.getBindingResult();
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        if (bindingResult.hasErrors()) {
197	            errors.addAllErrors(bindingResult);
198	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
199	                .map(fieldError -> {
200	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
201	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
202	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
203	                        fieldError.getField(),
204	                        defaultMessage,
205	                        rejectedValue);
206	                    return new ValidationMessageDto(message)
207	                        .putAdditionalProperty("field", fieldError.getField())
208	                        .putAdditionalProperty("rejectedValue", rejectedValue)
209	                        .putAdditionalProperty("defaultMessage", defaultMessage);
210	                })
211	                .toList();
212	            logger.debug("Validation error at {} {}: {}",
213	                request.getMethod(),
214	                request.getRequestURI(),
215	                bindingResult.getFieldErrors());
216	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
217	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
218	                .map(fieldError -> fieldError.getField())
219	                .distinct()
220	                .toList());
221	            return ResponseEntity.status(status).body(detail);
222	        }
223	        return ResponseEntity.status(status).body(detail);
224	    }
