9	/**
10	 * Builds an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION
11	 * is the region derived from the owner's postcode (see {@link Locality}) and HASH8 is the
12	 * first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName}.
13	 * The membership number, its check digit, the audit record and the locality all derive
14	 * from this identity; there is no per-city sequence any more.
15	 */
16	public final class CustomerCode {
17	
18	    private CustomerCode() {
19	    }
20	
21	    /** The owner's {@code <REGION>-<HASH8>} customer code. */
22	    public static String assign(Owner owner) {
23	        return Locality.of(owner.getCity(), owner.getPostcode())
24	            + "-" + hash8(owner.getTelephone() + owner.getLastName());
25	    }
26	
27	    /** The REGION component of a {@code <REGION>-<HASH8>} customer code. */
28	    public static String region(String customerCode) {
29	        return customerCode.substring(0, customerCode.indexOf('-'));
30	    }
31	
32	    /** First 8 upper-case hex characters of SHA-256 over {@code value}. */
33	    private static String hash8(String value) {
34	        byte[] digest = sha256(value);
35	        StringBuilder hex = new StringBuilder(8);
36	        for (int i = 0; i < 4; i++) {
37	            hex.append(String.format("%02X", digest[i]));
38	        }
39	        return hex.toString();
40	    }
41	
42	    private static byte[] sha256(String value) {
43	        try {
44	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
45	        }
46	        catch (NoSuchAlgorithmException e) {
47	            throw new IllegalStateException(e);
48	        }
49	    }
50	}
