1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality}: the canonical region. The postcode is preferred,
7	 * looked up by range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); when it is absent or
8	 * in no known range the fixed city-to-region table is used instead. Anything unresolved
9	 * resolves to {@code "UNKNOWN"}.
10	 */
11	public final class Locality {
12	
13	    private static final Map<String, String> CITY_REGION =
14	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
15	
16	    /** Postcode "hundreds" band (postcode / 100) -> region. */
17	    private static final Map<Integer, String> BAND_REGION =
18	        Map.of(20, "NSW", 30, "VIC", 40, "QLD");
19	
20	    private Locality() {
21	    }
22	
23	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not mapped. */
24	    public static String of(String city) {
25	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
26	    }
27	
28	    /** The region for {@code postcode} (preferred), falling back to {@code city}. */
29	    public static String of(String city, String postcode) {
30	        String region = byPostcode(postcode);
31	        return region != null ? region : of(city);
32	    }
33	
34	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
35	    private static String byPostcode(String postcode) {
36	        if (postcode == null) {
37	            return null;
38	        }
39	        return BAND_REGION.get(Integer.parseInt(postcode) / 100);
40	    }
41	}
